#include <atomic>
#include <thread>
static long shared;
static std::atomic<long> safe{0};
extern "C" void cpp_control(bool race) {
 auto work = [race] { for (int n = 0; n < 10000; ++n) { if (race) ++shared; else safe.fetch_add(1); } };
 std::thread a(work), b(work); a.join(); b.join();
}

