use std::sync::atomic::{AtomicUsize, Ordering};
static SAFE: AtomicUsize = AtomicUsize::new(0);
static mut RACY: usize = 0;
unsafe extern "C" { fn cpp_control(race: bool); }
fn main() {
 let mode = std::env::args().nth(1).unwrap();
 if mode.starts_with("cpp-") { unsafe { cpp_control(mode == "cpp-racy") }; return; }
 let race = mode == "rust-racy";
 std::thread::scope(|scope| {
  for _ in 0..2 { scope.spawn(move || {
   for _ in 0..10000 {
    if race { unsafe { let p = &raw mut RACY; p.write_volatile(p.read_volatile() + 1); } }
    else { SAFE.fetch_add(1, Ordering::SeqCst); }
   }
  }); }
 });
}
